Section ORACLE.
Context {O : Type}.
Variable pans : O -> aptr -> Z -> Z -> Z.     (* [comment removed for export] *)
Variable pupd : O -> ev -> Z -> O.            (* [comment removed for export] *)

Definition psel (o : O) (e : ev) : option Z :=
  match e with EPeek p c h => Some (pans o p c h) | _ => None end.
Definition prun {R} (o : O) (t : M R) : M (O * R) := ltac2:(Rpl.RP.run_i (rplG ()) 3 "U00$R;R{cd;$o;R/O;$t;R!1'1#2!8'0+2+3/O;'4/pupd;#3#2#1").

(* [comment removed for export] *)
Definition KREL {X R1 R2} (RR : O * R1 -> R2 -> Prop)
  (k1 : mstate -> X -> M R1) (k2 : mstate -> X -> M R2) : Prop :=
  forall o st cst x, cst = strip st -> strel RR (prun o (k1 st x)) (k2 cst x).
Definition KREL0 {R1 R2} (RR : O * R1 -> R2 -> Prop)
  (k1 : mstate -> M R1) (k2 : mstate -> M R2) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S05lcbd;g1d;lcd;g1d;lcd;g5d;<scbd;<scd;$R1;R{cd;$R2;R{cbd;$RR;R%~R!2+6/O;#2%~R#2w$k1;R%~R+7!1'1#4$k2;R%~R+7!1'1#4%o;R/O;%st;R+7%cst;R+7%~R!3+8+7#1!1'9#2!7+:+2+3!2+6/O;#9#8#7!3'5#9#4!1#6#3!1#5#2").
Definition BREL {R1 R2} (RR : O * R1 -> R2 -> Prop) (b1 : M R1) (b2 : M R2) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S05lcbd;g1d;lcd;g1d;lcd;g5d;<scbd;<scd;$R1;R{cd;$R2;R{cbd;$RR;R%~R!2+6/O;#2%~R#2w$b1;R!1'1#3$b2;R!1'1#3%o;R/O;!7+:+2+3!2+6/O;#6#5#4!3'5#6#1#3#2").
End ORACLE.
