Section TOP.
Context {O : Type} (pans : O -> aptr -> Z -> Z -> Z) (pupd : O -> ev -> Z -> O).
Local Notation KREL := (KREL pans pupd).
Local Notation BREL := (BREL pans pupd).

Definition CREL (x : O * (mstate * option (aptr * Z))) (y : mstate * option (aptr * Z)) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "U30!1+_:!2+6'<+3!2+6+70!3'K/O;1#2$x;R!2+6/O;1$y;R1!2+dX!3+8+7!1'9!3'A+702!3'A+70#1!3+80!3'K+702!3'K+70#1").

Lemma malloc_small_ctrl_ctrl {R1 R2} (RR : O * R1 -> R2 -> Prop) n k1 k2 b1 b2 :
  KREL RR k1 k2 -> BREL RR b1 b2 ->
