Lemma free_tail_slots_control st g idx o :
  strel (fun x y => strip (snd x) = strip y)
        ((prun pans pupd) o (free_tail dec_slots st g idx)) (free_tail dec_slots (strip st) g idx).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 4 "S20!1'dJ+7!1'9#4$st;R+7$g;R'<$idx;R+3$o;R/O;!9'g<00!6'g=/O;/pans;/pupd;+7+7$x;R!2+6/O;+7$y;R+7!3+8+7!1'9!3'K/O;+7#2!1'9#1#4#3#2#11!2,;+71").
Qed.

